export const config={id:'night-transit',title:'夜航路线',subtitle:'NIGHT TRANSIT / 07',description:'把城市想象成一张会呼吸的路线图。调节班次密度，观察光点如何沿三条路线穿越、停靠，再各自远去。原创虚构网络，不含实际地图或客流数据。',category:'coding-motion',useCase:'信息可视化',accent:'#f3bd72',duration:20,parameter:{label:'班次密度',min:1,max:6,step:1,value:3,unit:'级'}};
export const routes=[[[90,500],[255,500],[400,355],[590,355],[755,190],[1090,190]],[[120,200],[330,200],[500,370],[500,580],[660,650],[1085,650]],[[160,650],[330,480],[640,480],[780,340],[1080,340]]];
const colors=['#efb763','#7dc8ce','#c197db'];
export function pointOnRoute(points,u){const ls=points.slice(1).map((p,i)=>Math.hypot(p[0]-points[i][0],p[1]-points[i][1]));const total=ls.reduce((a,b)=>a+b,0);let d=Math.max(0,Math.min(1,u))*total;for(let i=0;i<ls.length;i++){if(d<=ls[i]||i===ls.length-1){const f=ls[i]?d/ls[i]:0;return [points[i][0]+(points[i+1][0]-points[i][0])*f,points[i][1]+(points[i+1][1]-points[i][1])*f]}d-=ls[i]}return [...points[0]]}
export function transitState(t,density){const n=2+Math.round(Math.max(1,Math.min(6,density)));return routes.flatMap((r,k)=>Array.from({length:n},(_,i)=>({route:k,point:pointOnRoute(r,((t/20*(k%2?-1:1)+i/n+k*.18)%1+1)%1)})))}
function path(ctx,points){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke()}
export function render(ctx,{t,value,width,height}){ctx.save();ctx.scale(width/1200,height/800);ctx.fillStyle='#0c1c2b';ctx.fillRect(0,0,1200,800);ctx.strokeStyle='#172f3d';ctx.lineWidth=1;for(let x=40;x<1200;x+=40){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,800);ctx.stroke()}for(let y=0;y<800;y+=40){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(1200,y);ctx.stroke()}
// A fictional river is part of the composition, not a borrowed map.
ctx.fillStyle='#102b3d';ctx.beginPath();ctx.moveTo(610,0);ctx.bezierCurveTo(420,220,810,360,660,540);ctx.bezierCurveTo(610,620,520,670,590,800);ctx.lineTo(735,800);ctx.bezierCurveTo(650,640,750,650,790,550);ctx.bezierCurveTo(940,320,580,200,745,0);ctx.closePath();ctx.fill();
ctx.fillStyle='#87a6b5';ctx.font='13px monospace';ctx.fillText('F I C T I O N A L   N E T W O R K',65,67);ctx.fillStyle='#f5f0e7';ctx.font='600 36px sans-serif';ctx.fillText('After hours, still connected.',65,113);ctx.font='12px monospace';ctx.fillStyle='#637f91';ctx.fillText('R I V E R',702,729);
routes.forEach((r,k)=>{ctx.strokeStyle='#091725';ctx.lineWidth=21;ctx.lineJoin='round';ctx.lineCap='round';path(ctx,r);ctx.strokeStyle=colors[k]+'47';ctx.lineWidth=9;path(ctx,r);ctx.strokeStyle=colors[k];ctx.lineWidth=2;path(ctx,r);r.forEach((p,i)=>{ctx.beginPath();ctx.arc(...p,i===2?11:6,0,Math.PI*2);ctx.fillStyle='#102231';ctx.fill();ctx.strokeStyle=colors[k];ctx.lineWidth=2;ctx.stroke();if(i===0||i===r.length-1){ctx.font='12px monospace';ctx.fillStyle='#a7b9c3';ctx.fillText((['EMBER','TIDE','IRIS'][k])+' '+(i===0?'01':'06'),p[0]-20,p[1]+29)}})});
for(const p of transitState(t,value)){let color=colors[p.route];const glow=ctx.createRadialGradient(...p.point,0,...p.point,22);glow.addColorStop(0,color+'80');glow.addColorStop(1,color+'00');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(...p.point,22,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff8dd';ctx.beginPath();ctx.arc(...p.point,4.5,0,Math.PI*2);ctx.fill()}
ctx.fillStyle='#a8bcc7';ctx.font='12px monospace';ctx.fillText('THREE ROUTES · ONE SHARED NIGHT',65,751);ctx.textAlign='right';ctx.fillStyle='#7a94a4';ctx.fillText('GENERATIVE DIAGRAM / NOT LIVE TRANSIT',1135,751);ctx.restore()}
